//		Where(iftacol.ReturnColumns.ID.Eq(), id)
func ReturnScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, ReturnColumns.OrganizationID, ReturnColumns.BusinessUnitID, ti)
}

// ReturnScopeTenantUpdate restricts an update query to a single tenant.
